package com.schooloss.fullnative.feature.attendance;
import android.os.Bundle;import android.view.*;import android.widget.*;import com.schooloss.fullnative.core.*;import org.json.*;import java.text.SimpleDateFormat;import java.util.*;
public final class AttendanceRegisterActivity extends BaseActivity {
 private int classId,sectionId;private String date;private final List<Integer> ids=new ArrayList<>();private final List<Spinner> statuses=new ArrayList<>();private final List<EditText> remarks=new ArrayList<>();
 @Override protected void onCreate(Bundle b){super.onCreate(b);classId=getIntent().getIntExtra("class_id",0);sectionId=getIntent().getIntExtra("section_id",0);date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());loading("Opening attendance","Loading native class register…");load();}
 private void load(){io.execute(()->{try{JSONObject r=api.get("attendance_register","class_id="+classId+"&section_id="+sectionId+"&date="+date);JSONObject d=r.optJSONObject("data");runOnUiThread(()->render(d));}catch(Exception e){runOnUiThread(()->error("Could not load attendance",e,this::load));}});}
 private void render(JSONObject d){ids.clear();statuses.clear();remarks.clear();LinearLayout p=Ui.v(this);p.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,24));p.setBackgroundColor(Constants.BG);TextView back=Ui.text(this,"‹  Attendance",12,Constants.BLUE,true);back.setOnClickListener(v->finish());p.addView(back);p.addView(Ui.text(this,d==null?"Attendance Register":d.optString("class_name","Attendance Register"),23,Constants.TEXT,true));p.addView(Ui.text(this,date+" · "+Ui.pretty(d==null?"open":d.optString("submission_status","open")),10,Constants.MUTED,false));JSONArray valid=d==null?null:d.optJSONArray("valid_statuses");List<String> opts=new ArrayList<>();if(valid!=null)for(int i=0;i<valid.length();i++)opts.add(valid.optString(i));if(opts.isEmpty())Collections.addAll(opts,"present","absent","late","half_day","leave","holiday");JSONArray rows=d==null?null:d.optJSONArray("rows");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);com.google.android.material.card.MaterialCardView c=Ui.card(this);LinearLayout in=Ui.v(this);in.setPadding(Ui.dp(this,13),Ui.dp(this,11),Ui.dp(this,13),Ui.dp(this,11));in.addView(Ui.text(this,r.optString("name","Student"),13,Constants.TEXT,true));in.addView(Ui.text(this,r.optString("admission_no","")+" · Roll "+r.optString("roll_no","—"),9,Constants.MUTED,false));Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,opts));int pos=opts.indexOf(r.optString("status","present"));s.setSelection(Math.max(0,pos));in.addView(s);EditText note=new EditText(this);note.setHint("Remarks (optional)");note.setText(r.optString("remarks",""));in.addView(note);ids.add(r.optInt("id"));statuses.add(s);remarks.add(note);c.addView(in);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.topMargin=Ui.dp(this,7);p.addView(c,lp);}if(d!=null&&d.optBoolean("can_mark",false)){com.google.android.material.button.MaterialButton save=Ui.button(this,"Submit Attendance",Constants.BLUE,0xFFFFFFFF);save.setOnClickListener(v->save());p.addView(Ui.gap(this,10));p.addView(save);}ScrollView sc=new ScrollView(this);sc.addView(p);setContentView(sc);}
 private void save(){loading("Submitting attendance","Applying SchoolOS attendance rules…");io.execute(()->{try{JSONObject b=new JSONObject();b.put("class_id",classId);b.put("section_id",sectionId);b.put("attendance_date",date);JSONArray a=new JSONArray();for(int i=0;i<ids.size();i++){JSONObject r=new JSONObject();r.put("student_id",ids.get(i));r.put("status",String.valueOf(statuses.get(i).getSelectedItem()));r.put("remarks",remarks.get(i).getText().toString());a.put(r);}b.put("statuses",a);api.post("attendance_save",b);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->error("Attendance was not saved",e,this::load));}});}
}